const palettes=[
  ['original','Original'],
  ['charcoal','Charcoal'],
  ['navy','Ink blue'],
  ['burgundy','Burgundy'],
  ['plum','Plum'],
  ['products','Casino felt · blue / teal'],
  ['felt-slate','Casino felt · slate / blue'],
  ['felt-teal','Casino felt · teal / silver'],
  ['jewel','Jewel tones'],
  ['smoked','Smoked felt'],
];
export function mountBuyPalettePicker(machine,onChange){
  const tools=document.createElement('details');tools.className='site-palette-tools';
  const summary=document.createElement('summary');summary.textContent='Preview options';tools.append(summary);
  const panel=document.createElement('div');panel.className='site-palette-tools__panel';
  const label=document.createElement('label');label.textContent='Buy-in quadrants';
  const select=document.createElement('select');select.setAttribute('aria-label','Buy-in quadrant colors');
  for(const [value,name] of palettes){const option=document.createElement('option');option.value=value;option.textContent=name;select.append(option);}
  label.append(select);panel.append(label);tools.append(panel);document.body.append(tools);
  let saved='felt-teal';try{saved=localStorage.getItem('two-widget-preview.palette')||saved;}catch{}
  saved=new URLSearchParams(location.search).get('palette')||saved;
  select.value=palettes.some(([key])=>key===saved)?saved:'felt-teal';
  machine.dataset.buyPalette=select.value;
  select.addEventListener('change',()=>{machine.dataset.buyPalette=select.value;try{localStorage.setItem('two-widget-preview.palette',select.value);}catch{}const url=new URL(location.href);url.searchParams.set('palette',select.value);history.replaceState(null,'',url);onChange?.();});
  tools.addEventListener('keydown',e=>{if(e.key==='Escape'){tools.open=false;summary.focus();}});
  document.addEventListener('pointerdown',e=>{if(!tools.contains(e.target))tools.open=false;});
  return panel;
}

export function mountGameLogoPicker(panel,machine,img,onChange){
  panel.closest('details').querySelector('summary').textContent='Preview options';
  const label=document.createElement('label');label.textContent='Degenerette logo';
  const select=document.createElement('select');select.setAttribute('aria-label','Degenerette logo');
  for(const [value,name] of [['compact','Rearranged original'],['original','Original']]){const option=document.createElement('option');option.value=value;option.textContent=name;select.append(option);}
  label.append(select);panel.append(label);
  let saved='compact';try{saved=localStorage.getItem('two-widget-preview.logo')||saved;}catch{}
  saved=new URLSearchParams(location.search).get('logo')||saved;
  select.value=saved==='original'?'original':'compact';
  const paint=()=>{
    machine.dataset.degeneretteLogo=select.value;
    img.src=new URL(select.value==='original'?'./art/degenerette-full-to-win-v22.png':'./art/degenerette-compact-to-win-v6.png',import.meta.url).href;
  };
  select.addEventListener('change',()=>{paint();try{localStorage.setItem('two-widget-preview.logo',select.value);}catch{}const url=new URL(location.href);url.searchParams.set('logo',select.value);history.replaceState(null,'',url);onChange?.();});
  paint();
}

export function mountZeroPicker(panel,headline){
  const label=document.createElement('label');label.textContent='Banner zero';
  const select=document.createElement('select');select.setAttribute('aria-label','Banner zero style');
  for(const [value,name] of [['plain','Plain zero'],['slashed','Original slashed zero']]){const option=document.createElement('option');option.value=value;option.textContent=name;select.append(option);}
  label.append(select);panel.append(label);
  let saved='plain';try{saved=localStorage.getItem('two-widget-preview.zero')||saved;}catch{}
  saved=new URLSearchParams(location.search).get('zero')||saved;
  select.value=saved==='slashed'?'slashed':'plain';
  const paint=()=>{headline.dataset.zeroStyle=select.value;};
  select.addEventListener('change',()=>{paint();try{localStorage.setItem('two-widget-preview.zero',select.value);}catch{}const url=new URL(location.href);url.searchParams.set('zero',select.value);history.replaceState(null,'',url);});
  paint();
}

export function mountLayoutPicker(panel){
  const label=document.createElement('label');label.textContent='Widget widths';
  const select=document.createElement('select');select.setAttribute('aria-label','Widget widths');
  for(const [value,name] of [['wide','Larger jackpot'],['balanced','Equal widths']]){
    const option=document.createElement('option');option.value=value;option.textContent=name;select.append(option);
  }
  label.append(select);panel.prepend(label);
  let saved='wide';try{saved=localStorage.getItem('two-widget-preview.layout')||saved;}catch{}
  saved=new URLSearchParams(location.search).get('layout')||saved;
  select.value=saved==='balanced'?'balanced':'wide';
  const paint=()=>{document.body.dataset.hubLayout=select.value;dispatchEvent(new Event('resize'));};
  select.addEventListener('change',()=>{
    paint();try{localStorage.setItem('two-widget-preview.layout',select.value);}catch{}
    const url=new URL(location.href);url.searchParams.set('layout',select.value);history.replaceState(null,'',url);
  });
  paint();
}
